//! Decoding property values, checked against what upstream `pyaaf2` decodes.
//!
//! The manifests here were generated by opening the same two fixture files
//! with `pyaaf2`, walking every object, and decoding every data property with
//! the type the file says it has. Matching them means two things at once: the
//! crate resolves a property to the same type definition upstream does, and it
//! reads the bytes of that type the same way.
//!
//! # Where the manifests differ from `pyaaf2`'s return value
//!
//! After a record's members are decoded, `pyaaf2` packages four of them into
//! Python objects: `TimeStruct`, `DateStruct` and `TimeStamp` become
//! `datetime` values and `Rational` becomes a `Fraction`. That is a layer on
//! top of the decode, and this crate hands back the members instead, so the
//! manifests record the members. Every member is still decoded by `pyaaf2`.
//! `AUID` and `MobID` are decoded whole on both sides, as they are single
//! values wearing a record's clothes.
//!
//! # What these fixtures do not reach
//!
//! Eight of the sixteen type categories appear in these two files: integers,
//! records, strings, enumerations, extendible enumerations, variable arrays,
//! renames and indirects. Fixed arrays, sets, characters, opaque values and
//! streams do not, and are covered by unit tests in the crate instead of being
//! quietly left untested here.

mod common;

use std::collections::HashMap;
use std::fs::File;

use aaf::property::PropertyValue;
use aaf::{AafFile, MetaDictionary};

use common::{data_dir, read_values_manifest, render};

/// A property upstream decoded and this crate could not even look up.
///
/// Not a decoding failure: the file's own meta dictionary is missing the
/// definition, and upstream fell back on the definitions it has built in.
#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Undefined {
    type_name: String,
    reason: &'static str,
}

/// Every data property of every object in both files, against `pyaaf2`.
///
/// Properties whose definition the file itself does not carry are counted
/// rather than compared, and the count is asserted, so the cost of not yet
/// carrying the built-in definitions is a number this test states rather than
/// coverage it quietly drops. Porting those definitions should take it to zero.
#[test]
fn matches_pyaaf2_on_every_decoded_value() {
    for (fixture, manifest, expected_count, expected_undefined) in [
        ("empty.aaf", "empty.values.tsv", 1284, 0),
        (
            "sector_size_512.aaf",
            "sector_size_512.values.tsv",
            2336,
            50,
        ),
    ] {
        let expected = read_values_manifest(manifest);
        assert_eq!(expected.len(), expected_count, "{manifest}");
        let by_key: HashMap<(&str, u16), &common::ValueRow> = expected
            .iter()
            .map(|row| ((row.path.as_str(), row.pid), row))
            .collect();

        let path = data_dir().join(fixture);
        let mut file =
            AafFile::open(File::open(&path).expect("fixture is readable")).expect("fixture opens");
        let metadict = MetaDictionary::read(&mut file).expect("the meta dictionary reads");

        let mut walked = file.walk().expect("the object tree is walkable");
        walked.sort_by(|a, b| a.0.cmp(&b.0));

        let mut compared = 0usize;
        let mut undefined = Vec::new();

        for (where_, object) in &walked {
            let mut properties = object.properties().to_vec();
            properties.sort_by_key(|p| p.pid);

            for property in &properties {
                if !matches!(property.value, PropertyValue::Data(_)) {
                    continue;
                }
                let row = by_key
                    .get(&(where_.as_str(), property.pid))
                    .unwrap_or_else(|| {
                        panic!(
                            "{fixture}: {where_} pid {} is not in the manifest",
                            property.pid
                        )
                    });

                let Some(def) = metadict.property(object.class_id(), property.pid) else {
                    undefined.push(Undefined {
                        type_name: row.type_name.clone(),
                        reason: "the class has no definition in the file",
                    });
                    continue;
                };
                let Some(type_def) = metadict.type_def(def.type_id) else {
                    undefined.push(Undefined {
                        type_name: row.type_name.clone(),
                        reason: "the type has no definition in the file",
                    });
                    continue;
                };

                assert_eq!(
                    type_def.name, row.type_name,
                    "{fixture}: {where_} pid {} resolves to the wrong type",
                    property.pid
                );
                let value = metadict.decode(def.type_id, property).unwrap_or_else(|e| {
                    panic!("{fixture}: {where_} {} does not decode: {e}", def.name)
                });
                assert_eq!(
                    render(&value),
                    row.value,
                    "{fixture}: {where_} pid {} ({}) decodes differently",
                    property.pid,
                    row.type_name
                );
                compared += 1;
            }
        }

        undefined.sort();
        undefined.dedup_by(|a, b| a == b);
        assert_eq!(
            compared + expected_undefined,
            expected.len(),
            "{fixture}: compared {compared}, leaving definitions the file omits: {undefined:?}"
        );
    }
}
